import {STATIONS} from './rail.js?v=business-site-analysis-2';
import {occupancy} from './utilities.js?v=business-site-analysis-2';
import {industrialJobs} from './industry.js?v=business-site-analysis-2';
function catchment(c,station){const n=Math.sqrt(c.tiles.length);const homes=new Set(),workplaces=new Set();let residents=0,jobs=0;
 for(let y=Math.max(0,station.y-3);y<=Math.min(n-1,station.y+3);y++)for(let x=Math.max(0,station.x-3);x<=Math.min(n-1,station.x+3);x++){const t=c.tiles[y*n+x];if(!t.level)continue;if(t.type==='residential'){homes.add(t.lotRoot??y*n+x);residents+=occupancy(t.level)*8;}else if(t.type==='commercial'||t.type==='industrial'){const places=t.type==='commercial'?occupancy(t.level)*6:industrialJobs(t);if(places>0){workplaces.add(t.lotRoot??y*n+x);jobs+=places;}}}
 return{homes:homes.size,residents,workplaces:workplaces.size,jobs};
}
export function stationDetails(c,t){
 if(!STATIONS[t.type])return null;const n=Math.sqrt(c.tiles.length),id=t.y*n+t.x,networks=(t.stationGroups||[]).map(i=>c.stats.railNetworks?.[i]).filter(Boolean),indices=[...new Set(networks.flatMap(g=>g.stations))].filter(i=>i!==id),local=catchment(c,t),connections=indices.map(i=>{const s=c.tiles[i];return{index:i,x:s.x,y:s.y,type:s.type,active:!!s.stationActive,activity:s.stationRiders||0,...catchment(c,s)};}),active=connections.filter(s=>s.active),reasons=[];
 if(c.transport.funding===0)reasons.push('Transit funding is zero.');if(c.transport.condition<=20)reasons.push('Transit equipment condition is too low. Restore funding and allow repairs.');if(c.transport.underfunded>=6)reasons.push('Transit workers are on strike. Restore 100% funding and run one month.');
 if(!t.stationNodes?.length)reasons.push(t.type==='trainStation'?'A train station needs rail directly beside it.':t.type==='subwayStation'?'A subway station needs subway track underneath or directly beside it.':'A rail–subway connection needs adjacent surface rail and subway underneath or directly beside it.');
 let advice=reasons.join(' ');
 if(!advice)advice=!connections.length?'This station has no other station on its track networks. Build and connect a destination station.':!active.length?'Connected stations are not operating. Check transit funding and track connections.':!local.homes&&!local.workplaces&&t.type!=='railTransfer'?'No occupied homes or developed workplaces are within three tiles. Place stations near the neighborhoods they serve.':local.homes&&!active.some(s=>s.jobs>0)?'Nearby residents have no developed workplaces near another operating station on these tracks. Connect a station near jobs.':local.workplaces&&!local.homes&&!active.some(s=>s.residents>0)?'Nearby jobs have no occupied homes near another operating station on these tracks. Connect a residential station.':t.stationRiders>0?'This station is handling passengers. Keep both ends of the journey supplied with homes and jobs.':'Tracks and stations are connected. Ridership still depends on available jobs, competing routes and stations, and transit funding and condition.';
 return{type:t.type,active:!!t.stationActive,activity:t.stationRiders||0,local,connections,railTiles:networks.reduce((v,g)=>v+g.railTiles,0),subwayTiles:networks.reduce((v,g)=>v+g.subwayTiles,0),monthlyCost:STATIONS[t.type].upkeep*c.transport.funding/100,reasons,advice};
}
export function stationReport(c,t){const d=stationDetails(c,t);if(!d)return'';const fmt=n=>n.toLocaleString(undefined,{maximumFractionDigits:1});return `<p>Tile ${t.x+1}, ${t.y+1} · ${d.active?'Operating':'Not operating'}</p><p>${d.advice}</p><div class="metric-grid"><div><small>Passenger activity</small><strong>${fmt(d.activity)}</strong></div><div><small>Monthly upkeep contribution</small><strong>§${fmt(d.monthlyCost)}</strong></div><div><small>Nearby occupied homes / residents</small><strong>${d.local.homes} / ${fmt(d.local.residents)}</strong></div><div><small>Nearby developed workplaces / jobs</small><strong>${d.local.workplaces} / ${fmt(d.local.jobs)}</strong></div><div><small>Connected rail / subway tiles</small><strong>${d.railTiles} / ${d.subwayTiles}</strong></div><div><small>Other operating / connected stations</small><strong>${d.connections.filter(s=>s.active).length} / ${d.connections.length}</strong></div></div><p>Neighborhood counts use the same three-tile square walking range as the routing simulation. Buildings intersecting that range count once, even when the building’s origin lies outside it. Resident and job totals include only tiles inside the range, matching the routing simulation. Counts describe nearby development; jobs can already be filled, and overlapping station neighborhoods share the same people and workplaces.</p><h3>Stations on these track networks</h3>${d.connections.length?`<div class="table-scroll"><table><thead><tr><th>Station</th><th>Status</th><th>Nearby residents / jobs</th><th>Activity</th></tr></thead><tbody>${d.connections.map(s=>`<tr><td>${STATIONS[s.type].name} · ${s.x+1}, ${s.y+1}</td><td>${s.active?'Operating':'Inactive'}</td><td>${fmt(s.residents)} / ${fmt(s.jobs)}</td><td>${fmt(s.activity)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No other connected stations.</p>'}<p class="fine">Activity includes boarding, alighting and transfers; adding station counts would count journeys more than once. Connected track networks do not guarantee a passenger journey. Station access and allocation rules are reconstruction calibration.</p><div class="actions"><button id="stationRailMap">Rail usage map</button><button id="stationSubwayMap">Subway map</button><button id="stationTransitBudget">Transit funding and planning</button></div>`;}
